return $input.all().map(item => {
  const r = item.json;
  const timezone = r.site_timezone || 'Europe/Paris';
  const date = new Date(r.debut);

  const dateFormatee = new Intl.DateTimeFormat('fr-FR', {
    timeZone: timezone,
    dateStyle: 'full'
  }).format(date);

  const heureFormatee = new Intl.DateTimeFormat('fr-FR', {
    timeZone: timezone,
    hour: '2-digit',
    minute: '2-digit'
  }).format(date);

  const nomComplet = [r.prenom, r.nom].filter(Boolean).join(' ');
  const manageUrl = `http://localhost:5680/manage-appointment?token=${r.token_gestion}`;

  let emailSubject;
  let emailText;

  switch (r.type) {
    case 'CONFIRMATION':
      emailSubject = `Confirmation de rendez-vous ${r.service_nom} - ${r.reference}`;
      emailText = `Bonjour ${nomComplet},

Votre rendez-vous consulaire est confirmé.

Référence : ${r.reference}
Service : ${r.service_nom}
Lieu : ${r.site_nom}
Adresse : ${r.site_adresse || 'À confirmer'}
Date : ${dateFormatee}
Heure : ${heureFormatee}

Merci de vous présenter à l'heure prévue avec les documents nécessaires à votre démarche.

Gérer, annuler ou replanifier votre rendez-vous :
${manageUrl}

Cordialement,

Service consulaire`;
      break;

    case 'ANNULATION':
      emailSubject = `Annulation du rendez-vous - ${r.reference}`;
      emailText = `Bonjour ${nomComplet},

Votre rendez-vous consulaire a bien été annulé.

Référence : ${r.reference}
Service : ${r.service_nom}
Lieu : ${r.site_nom}
Date initialement prévue : ${dateFormatee}
Heure : ${heureFormatee}
Motif : ${r.motif_annulation || 'Non renseigné'}

La place associée à ce rendez-vous a été libérée.

Cordialement,

Service consulaire`;
      break;

    case 'REPLANIFICATION':
      emailSubject = `Replanification du rendez-vous - ${r.reference}`;
      emailText = `Bonjour ${nomComplet},

Votre rendez-vous consulaire a bien été replanifié.

Référence : ${r.reference}
Service : ${r.service_nom}
Nouveau lieu : ${r.site_nom}
Adresse : ${r.site_adresse || 'À confirmer'}
Nouvelle date : ${dateFormatee}
Nouvelle heure : ${heureFormatee}

Gérer, annuler ou replanifier votre rendez-vous :
${manageUrl}

Cordialement,

Service consulaire`;
      break;

    default:
      throw new Error(`Type de notification non pris en charge : ${r.type}`);
  }

  return {
    json: {
      ...r,
      email_subject: emailSubject,
      email_text: emailText
    }
  };
});
